from collections import deque
import time
import os

class SEO_Crawler:
    def __init__(self, base_url):
        self.base_url = base_url
        self.crawled_links = set()
        self.queue = deque([base_url])

    def crawl(self, url):
        html = requests.get(url).text
        soup = BeautifulSoup(html, 'html.parser')

        yield url, soup

        for link in soup.find_all('a', href=True):
            href = link['href']
            relative_url = urljoin(url, href) if not is_absolute(href) else href
            if relative_url.startswith(self.base_url) and relative_url not in self.crawled_links:
                self.crawled_links.add(relative_url)
                yield from self.crawl(relative_url)

def urljoin(base, rel):
    return base[:base.rfind('/')+1] + rel

def is_absolute(href):
    return href.startswith('http')

def is_valid_url(url):
    try:
        result = requests.head(url)
        return result.status_code < 400
    except requests.RequestException:
        return False

def filter_out_non_text_links(html):
    return [a for a in html.find_all('a', href=True) 
            if a.attrs['href'].startswith('/') or is_absolute(a.attrs['href'])]

def main():
    urls_to_crawl = ['http://example.com']
    for url in urls_to_crawl:
        if is_valid_url(url):
            crawler = SEO_Crawler(url)
            for url, soup in crawler.crawl(url):
                print(url)
                for link in filter_out_non_text_links(soup):
                    print(" ", link.attrs['href'])
                print()
            time.sleep(1)  # 1 second between each page crawl

if __name__ == "__main__":
    main()
