url_categories = defaultdict(set)

def categorize_url(url):
    parsed_url = urlparse(url)
    if parsed_url.netloc.endswith(('.com', '.org', '.net')):
        return 'Business'
    elif parsed_url.netloc.endswith(('.edu')):
        return 'Education'
    elif parsed_url.netloc.endswith(('.gov')):
        return 'Government'
    elif parsed_url.path.endswith(('/wiki/')):
        return 'Wikipedia'
    elif url.endswith(('.pdf', '.docx', '.doc', '.xls', '.xlsx', '.ppt', '.pptx')):
        return 'Document'
    elif url.endswith(('.jpg', '.jpeg', '.png', '.gif')):
        return 'Image'
    elif url.endswith(('.mp3', '.mp4', '.wav')):
        return 'Audio'
    else:
        return 'Unknown'

def get_page(url):
    resp = requests.get(url)
    soup = BeautifulSoup(resp.text, 'html.parser')
    return soup

def get_links(soup):
    links = []
    for a in soup.find_all('a'):
        url = a.get('href')
        if url and url.startswith('http'):
            links.append(url)
    return links

def extract_urls_and_categorize(starting_url):
    categories = defaultdict(list)
    queue = [starting_url]
    while queue:
        url = queue.pop(0)
        soup = get_page(url)
        links = get_links(soup)
        category = categorize_url(url)
        categories[category].append(url)
        url_categories[category].add(url)
        for link in links:
            queue.append(link)
            category = categorize_url(link)
            if category not in categories:
                categories[category] = []
            categories[category].append(link)
            url_categories[category].add(link)
    return categories

def main():
    starting_url = input('Enter starting URL: ')
    categories = extract_urls_and_categorize(starting_url)
    for category, urls in categories.items():
        print(f"Category: {category}")
        for url in urls:
            print(url)
        print()

if __name__ == "__main__":
    main()
