class ServerSync:
    def __init__(self, source, destination, username, password, hostkey=None):
        self.source = source
        self.destination = destination
        self.username = username
        self.password = password
        self.hostkey = hostkey
        self.transport = None

    def connect(self):
        self.transport = paramiko.Transport((self.destination, 22))
        if self.hostkey is None:
            self.transport.connect(username=self.username, password=self.password)
        else:
            self.transport.connect(username=self.username, password=self.password)
            self.transport.auth_publickey(username=self.username, pkey=paramiko.RSAKey.from_private_key_file(self.hostkey))

    def disconnect(self):
        if self.transport is not None:
            self.transport.close()

    def get_files(self, path):
        files = []
        for r, d, f in os.walk(path):
            for file in f:
                files.append(os.path.join(r, file))
        return files

    def sync(self):
        self.connect()
        sftp = paramiko.SFTPClient.from_transport(self.transport)

        source_files = self.get_files(self.source)
        destination_files = sftp.listdir()

        for file in source_files:
            if os.path.isfile(file):
                file_name = os.path.basename(file)
                if file_name not in destination_files:
                    sftp.put(file, file_name)
                    print(f"Upload {file} to {self.destination}")

        for file in destination_files:
            sftp.remove(file)

        source_files = self.get_files(self.source)
        destination_files = self.get_files(self.destination)

        for file in destination_files:
            if os.path.isfile(file) and file not in source_files:
                sftp.get(file, file)
                print(f"Download {file} from {self.destination}")

        sftp.close()
        self.disconnect()

    def thread_sync(self):
        threads = []
        sftp = paramiko.SFTPClient.from_transport(self.transport)

        source_files_list = self.get_files(self.source)
        destination_files_list = sftp.listdir()

        for file in source_files_list:
            if os.path.isfile(file):
                file_name = os.path.basename(file)
                if file_name not in destination_files_list:
                    thread = threading.Thread(target=sftp.put, args=(file, file_name))
                    thread.start()
                    threads.append(thread)
                    print(f"Upload {file} to {self.destination}")
                elif file not in destination_files_list:
                    thread = threading.Thread(target=sftp.put, args=(file, file_name))
                    thread.start()
                    threads.append(thread)
                    print(f"Upload {file} to {self.destination}")

        for file in destination_files_list:
            sftp.remove(file)

        for file in destination_files_list:
            sftp.get(file, file)
            print(f"Download {file} from {self.destination}")

        for thread in threads:
            thread.join()

        sftp.close()
        self.disconnect()


