    pass

class FileTransfer:
    def __init__(self, src_path: str, dst_path: str):
        self.src_path = os.path.abspath(src_path)
        self.dst_path = os.path.abspath(dst_path)

    def compress(self):
        if not os.path.exists(self.src_path):
            raise FileTransferException(f"Source path {self.src_path} does not exist")

        try:
            with tarfile.TarFile(self.dst_path + '.tar.gz', mode='w:gz') as tf:
                tf.add(self.src_path)
            return self.dst_path + '.tar.gz'
        except tarfile.TarError as e:
            raise FileTransferException(f"Failed to compress file: {e}")

    def decompress(self):
        if not os.path.exists(self.dst_path + '.tar.gz'):
            raise FileTransferException(f"Destination path {self.dst_path} does not contain a tar file")

        try:
            with tarfile.TarFile(self.dst_path + '.tar.gz', mode='r:gz') as tf:
                tf.extractall(self.dst_path)
            return self.dst_path
        except tarfile.TarError as e:
            raise FileTransferException(f"Failed to decompress file: {e}")

    def copy(self):
        try:
            shutil.copy(self.src_path, self.dst_path)
            return self.dst_path
        except (FileNotFoundError, PermissionError) as e:
            raise FileTransferException(f"Failed to copy file: {e}")

