                target_file_path = os.path.join(target_root, file)
                if not os.path.exists(target_file_path) or file_modification_time_changed(target_file_path, source_file_path):
                    sync_file(source_file_path, target_file_path)

def file_modification_time_changed(source_path, target_path):
    source_mod_time = datetime.fromtimestamp(os.path.getmtime(source_path))
    target_mod_time = datetime.fromtimestamp(os.path.getmtime(target_path))
    return source_mod_time > target_mod_time

def sync_file(src, dst):
    if not os.path.exists(os.path.dirname(dst)):
        os.makedirs(os.path.dirname(dst))
    with open(src, 'rb') as fsrc, open(dst, 'wb') as fdst:
        while True:
            src_data = fsrc.read(4096)
            if not src_data:
                break
            fdst.write(src_data)

