class RemoteBackup:
    def __init__(self, host, username, password):
        self.host = host
        self.username = username
        self.password = password
        self.ftp = ftplib.FTP()
        self.ftp.connect(host)

    def login(self):
        try:
            self.ftp.login(user=self.username, passwd=self.password)
        except ftplib.all_errors as e:
            print(f"Login failed: {str(e)}")
            return False
        return True

    def create_directory(self, path):
        self.ftp.mkd(path)

    def send_file(self, local_path, remote_path):
        with open(local_path, 'rb') as f:
            self.ftp.storbinary(f"STOR {remote_path}", f)

    def backup_file(self, local_file, remote_dir, filename):
        file_path = os.path.join(remote_dir, filename)
        if not self.ftp.nlst(file_path):
            self.create_directory(remote_dir)
        self.send_file(local_file, file_path)

    def backup_dir(self, local_dir, remote_dir):
        for filename in os.listdir(local_dir):
            file_path = os.path.join(local_dir, filename)
            if os.path.isfile(file_path):
                self.backup_file(file_path, remote_dir, filename)
            elif os.path.isdir(file_path):
                dir_path = os.path.join(remote_dir, filename)
                self.create_directory(dir_path)
                self.backup_dir(file_path, dir_path)

    def close_connection(self):
        self.ftp.quit()


