import getpass
import paramiko
import os
import datetime
import netmiko

class NetworkConfigBackup:
    def __init__(self, hosts):
        self.hosts = hosts

    def backup_config(self, hostname, username, password):
        """Backup network device configuration."""
        device = {
            'device_type': 'Cisco_ios',
            'ip': hostname,
            'username': username,
            'password': password
        }

        try:
            session = netmiko.ConnectHandler(**device)
            config = session.send_command('show run')
            with open(f'{hostname}_{datetime.date.today()}.txt', 'w') as f:
                f.write(config)
            print(f'Config backup completed for {hostname}')
        except netmiko.NetmikoTimeoutException as e:
            print(f'Connection to {hostname} timed out: {e}')
        except paramiko.AuthenticationException:
            print(f'Authentication failed for {hostname}')
        finally:
            try:
                session.disconnect()
            except NameError:
                pass

    def backup_all(self, username, password):
        """Backup configurations of all devices."""
        for device in self.hosts:
            self.backup_config(device['hostname'], username, password)


